from produire import produire,paras,table,steps
parts=[
('L’ulcération traumatique est une perte de substance muqueuse provoquée par une agression locale. Les {causes possibles} comprennent morsure, dent, prothèse et brûlure.',paras('L’attribution au traumatisme reste une hypothèse à vérifier par la cicatrisation après suppression de la cause. Une tumeur peut être découverte près d’une dent coupante ; la proximité ne prouve pas la causalité.')),
('Les facteurs dentaires et prothétiques sont des causes importantes à rechercher. Les {terrains favorisants} peuvent ralentir la cicatrisation.',paras('Une bouche sèche, une prothèse mal adaptée ou des traumatismes répétés entretiennent la lésion. Le contexte de radiothérapie, d’immunodépression ou de dénutrition nécessite une vigilance particulière.')),
('Une agression répétée détruit l’épithélium et entretient l’inflammation. Les {mécanismes de persistance} expliquent pourquoi un simple traitement antalgique peut échouer.',paras('Le contact mécanique continue tant que l’arête dentaire, l’appareil ou l’habitude traumatique persiste. Le fond fibrineux peut paraître jaune sans constituer une preuve de surinfection bactérienne.')),
('Vérifier saignement, profondeur, hydratation et caractère suspect. Les {drapeaux rouges} ne sont pas annulés par un traumatisme rapporté.',paras('Induration, bord irrégulier, masse, adénopathie, saignement inexpliqué ou absence de guérison imposent un avis rapide. Une brûlure chimique importante, une extension infectieuse ou l’impossibilité de boire nécessite une évaluation urgente.')),
('Rechercher un événement précis et un contact répété. Les {questions ciblées} permettent de confronter localisation et mécanisme.',paras('Demander morsure, soin dentaire récent, nouvelle prothèse, dent cassée, aliments brûlants et produit appliqué dans la bouche. Préciser durée exacte, traitements déjà utilisés, tabac et alcool ; ne pas accepter sans examen le diagnostic que le patient attribue à sa lésion.')),
('Décrire l’ulcère et examiner la zone qui le touche. Les {gestes d’examen} doivent rechercher une cause et un signe de gravité.',paras('Inspecter dents, appareils et prothèses retirées ; évaluer taille, profondeur, douleur, induration et ganglions. Documenter la lésion pour comparer au contrôle ; ne pas tenter soi-même de meuler une dent ou de modifier une prothèse.')),
('Le siège peut soutenir une cause traumatique sans être spécifique. Le {diagnostic différentiel} comprend des maladies qui exigent une autre prise en charge.',table(['Profil','Alternative'],[['Ulcères récidivants à sites variables.','Aphtose.'],['Vésicules, gingivite et fièvre.','Gingivostomatite infectieuse.'],['Lésions multiples avec signes cutanés ou systémiques.','Maladie inflammatoire ou médicamenteuse.'],['Lésion unique persistante et indurée.','Carcinome ou autre lésion nécessitant une biopsie.']])) ,
('Le diagnostic est soutenu par un mécanisme compatible et une guérison après correction. Les {limites de cette preuve} doivent être expliquées au patient.',paras('Une amélioration de la douleur sans fermeture de l’ulcère ne suffit pas. L’absence de cicatrisation oblige à reprendre le diagnostic ; une lésion déjà suspecte doit être adressée sans attendre l’effet d’un essai local.')),
('Un bilan biologique n’est pas systématique pour un traumatisme simple. Les {examens complémentaires} sont indiqués si le tableau dépasse ce cadre.',paras('Un examen dentaire permet de corriger la cause. Une biopsie peut être nécessaire si la lésion reste inexpliquée, persiste ou paraît suspecte. Une suspicion d’infection profonde ou de lésion osseuse nécessite un bilan spécialisé.')),
('L’{arbre de décision} associe correction et contrôle. Le suivi est une partie indispensable du diagnostic.',steps('Repérer d’abord les signes d’alarme et adresser si présents.', 'Faire supprimer la cause dentaire ou prothétique par le professionnel compétent.', 'Soulager et protéger la muqueuse, puis fixer un contrôle de cicatrisation à court terme.', 'Adresser si absence d’amélioration ou persistance ; une ulcération inexpliquée atteignant trois semaines nécessite une évaluation spécialisée.')),
('Le traitement causal supprime l’agression locale. Les {soins associés} doivent favoriser le confort sans masquer une évolution anormale.',paras('Proposer alimentation tolérée, hygiène douce et antalgie adaptée au patient. Éviter produits caustiques, alcoolisés ou applications domestiques irritantes.', 'Un antibiotique n’est pas indiqué pour un ulcère traumatique simple sans infection étendue ni signe général. Ne pas répéter des corticoïdes locaux sur une lésion persistante sans diagnostic.')),
('La {prévention} repose sur des soins dentaires et prothétiques adaptés. Le patient doit savoir quels changements imposent un contrôle.',paras('Faire réparer une dent coupante et ajuster une prothèse blessante. Éviter morsures répétées et aliments brûlants ; consulter en cas de nouvelle masse, saignement ou persistance.')),
('Le traumatisme apparent ne suffit pas au diagnostic final. La guérison doit être vérifiée après correction. Une lésion suspecte est adressée immédiatement et une persistance inexpliquée impose un bilan.','')]
quiz=[('Une dent coupante suffit-elle à prouver la cause ?','Non : vérifier la guérison après correction.'),('Une lésion tumorale peut-elle être douloureuse ?','Oui ; la douleur ne l’exclut pas.'),('Un fond jaune prouve-t-il une infection bactérienne ?','Non : il peut être fibrineux.'),('Faut-il examiner sous la prothèse ?','Oui.'),('Le patient doit-il meuler lui-même sa dent ?','Non : le geste relève du professionnel dentaire.'),('Un traitement antalgique corrige-t-il le traumatisme ?','Non : la cause mécanique persiste si elle n’est pas supprimée.'),('Une amélioration de douleur suffit-elle ?','Non : il faut contrôler la fermeture de la lésion.'),('Que faire devant induration et ganglion cervical ?','Adresser rapidement pour bilan spécialisé.'),('Une biopsie est-elle obligatoire pour toute morsure récente ?','Non : elle est ciblée sur doute, persistance ou suspicion.'),('L’antibiotique est-il systématique ?','Non dans un traumatisme simple sans signes infectieux étendus.'),('Un produit caustique accélère-t-il la cicatrisation ?','Il peut aggraver la lésion ; ne pas l’utiliser.'),('À quel délai une ulcération inexpliquée doit-elle être évaluée ?','Si elle persiste trois semaines, plus tôt si suspecte.'),('Une radiothérapie antérieure change-t-elle la vigilance ?','Oui : cicatrisation et diagnostics possibles sont modifiés.'),('Quel est le couple indispensable de la prise en charge ?','Correction de la cause et contrôle de cicatrisation.')]
produire(5,parts,quiz,(2,10,12,13,21))
